import 'dart:convert';
import 'dart:io';

import 'package:cloud_firestore/cloud_firestore.dart';

/// The shared Firestore fixtures (shared/fixtures/firestore_documents.json, generated by
/// scripts/export_fixtures.mjs): the same documents the rules tests write through the real rules.
/// Tests run from web/, so the path is relative to it.
abstract final class SharedFixtures {
  static final Map<String, Object?> _root =
      jsonDecode(File('../shared/fixtures/firestore_documents.json').readAsStringSync()) as Map<String, Object?>;

  /// The fixed time `{"$serverTimestamp": true}` becomes here (what the server would write).
  static final Timestamp serverTime = Timestamp.fromMillisecondsSinceEpoch(1761048000000);

  static Map<String, Object?> get constants => _root['constants']! as Map<String, Object?>;

  static String constant(String name) => constants[name]! as String;

  /// A fresh copy of document [name], placeholders resolved ([args] for `{"$arg": …}`), with
  /// [overrides] applied on top (a null value removes the field).
  static Map<String, Object?> document(
    String name, {
    Map<String, Object?> args = const {},
    Map<String, Object?> overrides = const {},
  }) {
    final documents = _root['documents']! as Map<String, Object?>;
    final resolved = _resolve(documents[name], args)! as Map<String, Object?>;
    for (final MapEntry(:key, :value) in overrides.entries) {
      if (value == _remove) {
        resolved.remove(key);
      } else {
        resolved[key] = value;
      }
    }
    return resolved;
  }

  /// Document [name] exactly as the JSON has it (placeholders such as `{"$serverTimestamp": true}`
  /// kept), to compare with what the web's write mappers produce.
  static Map<String, Object?> raw(String name) =>
      jsonDecode(jsonEncode((_root['documents']! as Map<String, Object?>)[name])) as Map<String, Object?>;

  /// The tombstone of a document whose id field is [idField] = [id].
  static Map<String, Object?> tombstone(String idField, String id) => {idField: id, ...document('tombstone')};

  /// An override value that removes the field.
  static const Object remove = _remove;
  static const Object _remove = Object();

  static Object? _resolve(Object? value, Map<String, Object?> args) {
    if (value is List) return [for (final item in value) _resolve(item, args)];
    if (value is Map) {
      if (value[r'$serverTimestamp'] == true) return serverTime;
      final arg = value[r'$arg'];
      if (arg is String) {
        if (!args.containsKey(arg)) throw ArgumentError('fixture needs the argument $arg');
        return args[arg];
      }
      return <String, Object?>{for (final MapEntry(:key, :value) in value.entries) '$key': _resolve(value, args)};
    }
    return value;
  }
}
